n, k = input().split()
k = int(k)

n_str = n
count_zero = 0
remove_count = 0

# Scan from right to left
for digit in reversed(n_str):
    if digit == '0':
        count_zero += 1
        if count_zero == k:
            break
    else:
        remove_count += 1

if count_zero == k:
    print(remove_count)
else:
    # Not enough zeros, answer is length - 1 (keep one zero)
    print(len(n_str) - 1)
